import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    words = data[1:]

    if n == 0:
        print("")
        return

    result = words[0]

    for i in range(1, n):
        current = words[i]
        max_overlap = 0

        min_len = min(len(result), len(current))

        for overlap_len in range(min_len, 0, -1):
            if result.endswith(current[:overlap_len]):
                max_overlap = overlap_len
                break

        result += current[max_overlap:]

    print(result)

if __name__ == "__main__":
    main()
